seq_lines = []
with open("region.fasta") as f:
    for line in f:
        line=line.strip()
        if not line.startswith(">") and line:
            seq_lines.append(line)
seq = "".join(seq_lines).upper()

stops = {"TAA","TAG","TGA"}
starts = {"ATG"}
def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

results = {}
for strand, s in [("+", seq), ("-", revcomp(seq))]:
    for frame in range(3):
        orfs = []  # (start_index_in_s, stop_index_exclusive, len_trip)
        i = frame
        cur_start = None
        while i+3 <= len(s):
            codon = s[i:i+3]
            if codon in starts and cur_start is None:
                # greedy: take first ATG after last stop
                cur_start = i
            if codon in stops:
                if cur_start is not None:
                    orfs.append((cur_start, i, (i-cur_start)//3, cur_start//1))
                    cur_start = None
                # also record an ORF from previous stop to this stop (longest possible, no internal start requirement)
                cur_start = i+3
            i += 3
        # dangling
        results[(strand,frame)] = orfs

# Report ORFs >= 90 aa (270 nt) that begin with ATG
print("ORFs (ATG..STOP) >= 90 aa:")
allorfs=[]
for (strand,frame), orfs in results.items():
    for st, en, aa, _ in orfs:
        if aa >= 90:
            allorfs.append((aa, strand, frame, st, en))
allorfs.sort(reverse=True)
for aa, strand, frame, st, en in allorfs:
    print(f"strand {strand} frame {frame}: nt {st}-{en} ({en-st} bp), {aa} aa")
